      [style.transform]="transform()"
    >
      <span class="sitzplan-page__corner"></span>
      @for (column of columnNumbers(); track column) {
        <span class="sitzplan-page__column-label">{{ column }}</span>
      }
      @for (rowGroup of rowsWithCells(); track rowGroup.row) {
        <span class="sitzplan-page__row-label">{{ rowGroup.row }}</span>
        @for (cell of rowGroup.cells; track $index) {
          @if (cell.seat; as seat) {
            <app-seat [row]="seat.row" [column]="seat.column" [status]="seat.status" />
          } @else {
            <div class="sitzplan-page__aisle"></div>
          }
        }
      }
    </div>
  </div>
} @else {
  <div
    class="sitzplan-page__grid sitzplan-page__grid--placeholder"
    [style.grid-template-columns]="'repeat(' + placeholderColumns + ', minmax(32px, 1fr))'"
    aria-busy="true"
    aria-label="Sitzplan wird geladen"
  >
    @for (cell of placeholderCells; track $index) {
      <div class="sitzplan-page__placeholder-cell"></div>
    }
  </div>
}

